(971, 'TOTAL_REQUIREMENTS', '<ul><li>Importējamais fails jābūt Excel 2003 formātā. </li>\r\n            <li>Kolonnas virsraksti netiek importēti. </li>\r\n            <li>Kolonas secība ir obligāta. </li>\r\n<li>Failā jābūt tikai predefinētas kolonnas. </li>\r\n        </ul>Importējama faila kolonas saturs:'),
(972, 'REQUIREMENTS_EDAREA', '<table cellpadding="3" cellspacing="0" border="1" width="100%">\r\n        <tr>\r\n           <th>Kolonas dati</th>\r\n           <th>Obligāts</th>\r\n           <th>Kolonas datu apraksts</th>\r\n        </tr>\r\n        <tr>\r\n            <td>Kods</td>\r\n            <td>+</td>\r\n            <td>ED iecirkņa kods. Unikāls. Var saturēt tikai sekojošus simbolus  `0`-`9`. Maksimāli 5 simboli. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Reģions</td>\r\n            <td>+</td>\r\n            <td>Reģiona kods. Var saturēt tikai sekojošus simbolus  `A`-`Z`. Maksimāli 3 simboli. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Nosaukums.</td>\r\n            <td>+</td>\r\n            <td>ED iecirkņa nosaukums. Maksimāli 30 simboli. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>ED nodaļa</td>\r\n            <td>+</td>\r\n            <td>Maksimāli 30 simboli.</td>\r\n        </tr>\r\n       </table>'),
(973, 'REQUIREMENTS_MMS_WORKS', '<table cellpadding="3" cellspacing="0" border="1" width="100%">\r\n        <tr>\r\n           <th>Kolonas dati</th>\r\n           <th>Obligāts</th>\r\n           <th>Kolonas datu apraksts</th>\r\n        </tr>\r\n        <tr>\r\n            <td>Kods</td>\r\n            <td>+</td>\r\n            <td>MMS darba kods. Maksimāli 150 simboli. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Cilvekstundas</td>\r\n            <td>+</td>\r\n            <td>Cipars formatā [xxxxx.xx]. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Materiāla izmaksas</td>\r\n            <td>+</td>\r\n            <td>Cipars formatā [xxxxx.xx]. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Ceturksnis</td>\r\n            <td>+</td>\r\n            <td>Atļautas vērtības: 1, 2, 3, 4. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Gads</td>\r\n            <td>+</td>\r\n            <td>Cipars formatā [xxxx]. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Problemobjekts</td>\r\n            <td>+</td>\r\n            <td>Atļautas vērtības: 0, 1 </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Struktūrvienības kods</td>\r\n            <td>+</td>\r\n            <td>Cipars formatā [xxxx]. </td>\r\n        </tr>\r\n<tr>\r\n            <td>Darbuzņēmējs</td>\r\n            <td>-</td>\r\n            <td>Darbuzņēmēja identifikators. Cipars.</td>\r\n        </tr>\r\n<tr>\r\n            <td>DU trases</td>\r\n            <td>+</td>\r\n            <td>Atļautas vērtības: 0, 1 </td>\r\n        </tr>\r\n        <tr><td>1z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>2z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>3z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>4z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>5z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>6z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>7z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>8z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>9z</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>1v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>2v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>3v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>4v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>5v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>6v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>7v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>8v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>9v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>10v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n        <tr><td>11v</td><td>+</td><td>Cipars formatā [xxxxx.xx].</td></tr>\r\n       </table>'),
