(1023, 'REQUIREMENTS_CALCULATION', '<table cellpadding="3" cellspacing="0" border="1" width="100%">\n        <tr>\n           <th>Kolonas dati</th>\n           <th>Obligāts</th>\n           <th>Kolonas datu apraksts</th>\n        </tr>\n        <tr>\n            <td>Grupas kods</td>\n            <td>+</td>\n            <td>Kalkulācijas grupas kods. Var saturēt tikai sekojošus simbolus `a`-`z`, `A`-`Z`, `0`-`9`. Maksimāli 5 simboli. </td>\n        </tr>\n        <tr>\n            <td>Kalkulācijas šifrs</td>\n            <td>+</td>\n            <td>Kalkulācijas šifrs. Unikāls. Var saturēt tikai sekojošus simbolus `0`-`9`. Maksimāli 5 simboli.</td>\n        </tr>\n        <tr>\n            <td>Kalkulācijas nosaukums</td>\n            <td>+</td>\n            <td>Kalkulācijas nosaukums. Maksimāli 150 simboli.</td>\n        </tr>\n        <tr>\n            <td>Mērvienība</td>\n            <td>+</td>\n            <td>Kalkulācijas mērvienība. Maksimāli 15 simboli. </td>\n        </tr>\n         <tr>\n            <td>Apraksts</td>\n            <td>-</td>\n            <td>Kalkulācijas apraksts. Maksimāli 2000 simboli. </td>\n        </tr>\n        <tr>\n            <td>Fiziskais rādītājs</td>\n            <td>-</td>\n            <td>Fiziska rādītāja pazime. Var saturēt tikai sekojošus simbolus [`2`-`9`]`z` vai [`2`-`11`]`v`. Maksimāli 3 simboli. </td>\n        </tr>\n       	<tr>\n            <td>Darbuzņēmējs</td>\n            <td>-</td>\n            <td>Darbuzņēmēja identifikators. Cipars.</td>\n        </tr>\n	<tr>\n            <td>ED nodaļa</td>\n            <td>-</td>\n            <td>ED nodaļas nosaukums. Maksimāli 250 simboli. </td>\n        </tr>\n	<tr>\n            <td>Plāna cena</td>\n            <td>-</td>\n            <td>Plāna darbu cena. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n	<tr>\n            <td>Neplāna cena</td>\n            <td>-</td>\n            <td>Neplāna darbu cena. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>1</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>2</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>3</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>4</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>5</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>6</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>7</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>8</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>9</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n        <tr>\n            <td>10</td>\n            <td>-</td>\n            <td>Papildus kolonna. Cipars formatā [xxxxx.xx]. </td>\n        </tr>\n       </table>'),
